+    /**
+     * Genera un slug URL-amigable a partir del nombre del item.
+     * Formato: {id}-{nombre-slugificado} (ej: 139-diplomado-especializado-en-ssoma-en-mineria)
+     * Resuelve colisiones buscando el id disponible más cercano (id+1, id+2, ...).
+     */
+    public static function generateSlug(string $name, int $id): string
+    {
+        $baseSlug = Str::slug($name);
+
+        if ($baseSlug === '') {
+            $baseSlug = 'programa';
+        }
+
+        $slug = $id . '-' . $baseSlug;
+
+        // Si el slug está libre, usarlo tal cual
+        if (! self::where('slug', $slug)->where('id', '!=', $id)->exists()) {
+            return $slug;
+        }
+
+        // Resolver colisión probando id+1, id+2, ...
+        $candidateId = $id + 1;
+        do {
+            $slug = $candidateId . '-' . $baseSlug;
+            $candidateId++;
+        } while (self::where('slug', $slug)->where('id', '!=', $id)->exists());
+
+        return $slug;
+    }
+
+    /**
