}

/* === CATÁLOGO: SIDEBAR + TOOLBAR + EMPTY STATE === */
.catalog-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 22px;
}

.catalog-count {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.92rem;
}

.catalog-count strong {
    color: var(--text-main);
}

.filter-chip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 0.85rem;
    font-weight: 600;
    color: #ce1212;
    background: rgba(206, 18, 18, 0.08);
    border: 1px solid rgba(206, 18, 18, 0.25);
    border-radius: 50px;
    padding: 7px 8px 7px 16px;
    text-decoration: none;
    transition: all 0.3s ease;
}

.filter-chip:hover {
    background: #ce1212;
    color: #fff;
}

.filter-chip span {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: rgba(206, 18, 18, 0.15);
    font-size: 1rem;
    line-height: 1;
}

.filter-chip:hover span {
    background: rgba(255, 255, 255, 0.25);
}

.modern-sidebar {
    position: sticky;
    top: 100px;
}

.modern-sidebar h4 {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--text-main);
    margin: 0 0 16px;
    padding-bottom: 12px;
    border-bottom: 2px solid rgba(206, 18, 18, 0.2);
}

.modern-category-list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.modern-category-list a {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 11px 14px;
    border-radius: 10px;
    color: var(--text-main);
    font-size: 0.92rem;
    font-weight: 500;
    text-decoration: none;
    border: 1px solid transparent;
    transition: all 0.25s ease;
}

.modern-category-list a i {
    font-size: 0.7rem;
    color: var(--text-muted);
    transition: all 0.25s ease;
}

.modern-category-list a:hover {
    background: rgba(206, 18, 18, 0.07);
    color: #ce1212;
    transform: translateX(4px);
}

.modern-category-list a:hover i {
    color: #ce1212;
}

.modern-category-list a.active {
    background: rgba(206, 18, 18, 0.1);
    border-color: rgba(206, 18, 18, 0.3);
    color: #ce1212;
    font-weight: 700;
    box-shadow: inset 3px 0 0 #ce1212;
}

.modern-category-list a.active i {
    color: #ce1212;
}

.catalog-help {
    margin-top: 22px;
    padding: 22px 20px;
    border-radius: 14px;
    background: linear-gradient(135deg, #14161d 0%, #3d0d0f 100%);
    color: #fff;
    text-align: center;
}

.catalog-help h5 {
    font-size: 1rem;
    font-weight: 700;
    margin: 0 0 6px;
    color: #fff;
}

.catalog-help p {
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.75);
    margin: 0 0 14px;
}

.catalog-help .cta-btn {
    width: 100%;
    font-size: 0.88rem;
    padding: 12px 18px;
}

.catalog-empty {
    text-align: center;
    padding: 60px 30px;
    background: var(--bg-card);
    border: 1px dashed var(--border-color);
    border-radius: 16px;
}

.catalog-empty-icon {
    width: 72px;
    height: 72px;
    margin: 0 auto 18px;
    border-radius: 20px;
    background: rgba(206, 18, 18, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
}

.catalog-empty-icon svg {
    width: 32px;
    height: 32px;
    color: #ce1212;
}

.catalog-empty h4 {
    color: var(--text-main);
    font-weight: 700;
    margin-bottom: 8px;
}

.catalog-empty p {
    color: var(--text-muted);
    margin-bottom: 22px;
}

.catalog-empty .program-btn {
    display: inline-block;
    padding: 12px 30px;
}

@media (max-width: 991px) {
    .modern-sidebar {
        position: static;
    }
}","allowMultiple":false}]}}


