/* === PERFIL DEL ESTUDIANTE === */
.profile-card {
    display: flex;
    align-items: center;
    gap: 22px;
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 18px;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.08);
    padding: 26px 28px;
    margin-bottom: 30px;
}

.profile-photo {
    width: 96px;
    height: 96px;
    flex-shrink: 0;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid rgba(206, 18, 18, 0.25);
    background: rgba(206, 18, 18, 0.1);
    display: flex;
    align-items: center;
    justify-content: center;
}

.profile-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.profile-initials {
    font-size: 1.6rem;
    font-weight: 800;
    color: #ce1212;
}

.profile-info h2 {
    margin: 0 0 8px;
    font-size: 1.4rem;
    font-weight: 800;
    color: var(--text-main);
    line-height: 1.3;
}

.profile-role {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: #ce1212;
    background: rgba(206, 18, 18, 0.1);
    border-radius: 50px;
    padding: 5px 16px;
}

.profile-count {
    margin: 10px 0 0;
    color: var(--text-muted);
    font-size: 0.92rem;
}

.profile-count strong {
    color: var(--text-main);
}

.profile-section-head {
    margin: 6px 0 22px;
}

.profile-section-head h3 {
    margin: 0 0 4px;
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--text-main);
}

.profile-section-head p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.92rem;
}

@media (max-width: 575px) {
    .profile-card {
        flex-direction: column;
        text-align: center;
        padding: 22px 18px;
    }
    .profile-info h2 {
        font-size: 1.15rem;
    }
}","allowMultiple":false}]}}


